<script lang="ts">
  import { enhance } from '$app/forms';
  import type { PageProps } from './$types';
  let { data, form }: PageProps = $props();
  let tab = $state('overview');
  const d = $derived(data.dashboard);
  const students = $derived(d?.students ?? []);
  const gaps = $derived(students.filter((s: any) => s.cpmks.some((c: any) => c.status === 'gap')).length);
  const complete = $derived(students.filter((s: any) => s.cpmks.every((c: any) => c.complete)).length);
</script>

<svelte:head><title>Campus Assistant — Academic Outcomes</title><meta name="description" content="Pantau capaian pembelajaran dan rencanakan intervensi berbasis bukti."/></svelte:head>

<div class="app">
  <aside>
    <a class="brand" href="/"><span class="logo">CA</span><span>Campus<span class="brand-sub">Assistant</span></span></a>
    <div class="eyebrow">ACADEMIC WORKSPACE</div>
    <nav aria-label="Navigasi utama">
      {#each [['overview', '◫', 'Ringkasan kelas'], ['interventions', '◎', 'Intervensi'], ['roi', '↗', 'Evaluasi pilot']] as item}
        <button class:active={tab === item[0]} onclick={() => tab = item[0]}><span>{item[1]}</span>{item[2]}</button>
      {/each}
    </nav>
    <div class="sidebar-note"><span class="dot"></span> Evidence first<p>Rekomendasi ditinjau dosen. Setiap keputusan memiliki jejak bukti.</p></div>
    <div class="user"><div class="avatar">AL</div><div>Workspace dosen<small>Pilot satu kelas</small></div></div>
  </aside>
  <main>
    <header><span>Workspace / <strong>{tab === 'overview' ? 'Ringkasan kelas' : tab === 'interventions' ? 'Intervensi' : 'Evaluasi pilot'}</strong></span><div class="header-right"><span class="pill">Data sintetis</span>{#if d}<form method="POST" action="?/logout"><button class="quiet">Keluar</button></form>{/if}</div></header>
    <section class="content">
      {#if form?.error || data.error}<div class="notice error" role="alert">{form?.error || data.error}</div>{/if}
      {#if form?.success}<div class="notice" role="status">{form.success}</div>{/if}
      {#if !d}
        <div class="login-panel"><div class="eyebrow">CAMPUS ASSISTANT</div><h1>Keputusan akademik<br/>berbasis bukti.</h1><p>Masuk untuk memantau capaian, meninjau learning gap, dan merencanakan intervensi.</p><form method="POST" action="?/login" use:enhance><label>Username<input name="username" autocomplete="username" value="dosen" required/></label><label>Password<input name="password" type="password" autocomplete="current-password" required/></label><button class="primary">Masuk ke workspace →</button></form><small>Gunakan password yang Anda tetapkan saat seed database.</small></div>
      {:else}
        <div class="page-title"><div><div class="eyebrow">SEMESTER GANJIL • PILOT</div><h1>{tab === 'overview' ? 'Setiap capaian, langkah berikutnya.' : tab === 'interventions' ? 'Intervensi yang dapat ditinjau.' : 'Buktikan manfaat sebelum perluasan.'}</h1><p>{d.name} · Bukti pembelajaran dalam satu pandangan.</p></div><span class="pill outlined">{d.id}</span></div>
        <div class="stats"><article><span>Mahasiswa</span><strong>{students.length}<small>peserta sintetis</small></strong><p>Satu kelas terpantau</p></article><article><span>Memiliki learning gap</span><strong>{gaps}<small>mahasiswa</small></strong><p>Prioritas review dosen</p></article><article><span>Data lengkap</span><strong>{complete}<small>dari {students.length}</small></strong><p>Missing tidak dihitung nol</p></article><article class="roi-stat"><span>Keputusan release</span><strong>HOLD</strong><p>Bukti ROI belum lengkap</p></article></div>
        {#if tab === 'overview'}
          <div class="section-heading"><div><h2>Capaian pembelajaran</h2><p>Angka dihitung deterministik. CPL berlaku untuk bukti mata kuliah ini.</p></div><span class="pill">Weighted course v1</span></div>
          <div class="table-wrap"><table><thead><tr><th>Mahasiswa</th><th>CPMK 01</th><th>CPMK 02</th><th>CPMK 03</th><th>Status bukti</th><th>Tindak lanjut</th></tr></thead><tbody>{#each students as s}<tr><td><strong>{s.name}</strong><small>{s.id}</small></td>{#each s.cpmks as c}<td><span class:score-gap={c.status === 'gap'}>{c.score ?? '—'}</span><small>target {c.target}</small></td>{/each}<td><span class="badge" class:amber={!s.cpmks.every((c: any) => c.complete)}>{s.cpmks.every((c: any) => c.complete) ? 'Lengkap' : 'Belum lengkap'}</span></td><td>{#if s.cpmks.every((c: any) => c.complete) && s.cpmks.some((c: any) => c.status === 'gap')}<form method="POST" action="?/draft" use:enhance><input type="hidden" name="class_id" value={d.id}/><input type="hidden" name="student_id" value={s.id}/><input type="hidden" name="key" value={`${s.id}-${s.snapshot}`}/><button class="mini">Buat draft ↗</button></form>{:else}<span class="muted">{s.cpmks.every((c: any) => c.complete) ? 'Target tercapai' : 'Lengkapi data'}</span>{/if}</td></tr>{/each}</tbody></table></div>
