          {#each d.interventions as i}<article class="panel intervention"><div class="section-heading"><h2>{i.student_id}</h2><span class="badge" class:amber={i.status === 'draft'}>{i.status === 'draft' ? 'Menunggu review' : 'Disetujui'}</span></div>{#each i.content.activities as a}<div class="activity"><strong>{a.cpmk_id} · gap {a.gap}</strong><p>{a.task}</p><small>Bukti: {a.evidence_ids.join(', ')} · {a.duration_minutes} menit</small><p>{a.assessment_plan}</p></div>{/each}{#if i.status === 'draft'}<form method="POST" action="?/approve" use:enhance><input type="hidden" name="class_id" value={d.id}/><input type="hidden" name="id" value={i.id}/><button class="primary">Setujui rencana setelah review ✓</button></form>{/if}</article>{/each}
        {:else}
          <div class="bottom-grid"><article class="panel"><h2>Catat pengukuran kasus</h2><p>A: proses manual · B: aplikasi non-AI · C: aplikasi + AI. Arm C baru dinilai setelah provider AI tersedia.</p><form class="measurement" method="POST" action="?/measure" use:enhance><input type="hidden" name="class_id" value={d.id}/><label>ID kasus<input name="case_id" required placeholder="CASE-001"/></label><label>Arm<select name="arm"><option>A</option><option>B</option><option>C</option></select></label><label>Waktu kerja (menit)<input name="minutes" type="number" min="0" step="0.1" required/></label><label>Review (menit)<input name="review" type="number" min="0" step="0.1" value="0" required/></label><label>Koreksi (menit)<input name="correction" type="number" min="0" step="0.1" value="0" required/></label><label>Biaya (Rp)<input name="cost" type="number" min="0" step="1" value="0" required/></label><button class="primary">Simpan pengukuran</button></form></article><article class="panel"><div class="eyebrow">GO / NO-GO</div><h2>Bukti dulu, perluasan kemudian.</h2><p>{data.measurement?.reason}</p><div class="notice">Status: HOLD. Penghematan waktu merupakan manfaat kapasitas, bukan otomatis penghematan kas.</div>{#each data.measurement?.records ?? [] as r}<div class="measurement-row"><strong>{r.case_id} · {r.arm}</strong><span>{r.total_minutes} menit · Rp{r.cost_idr}</span></div>{/each}</article></div>
        {/if}
      {/if}
      <footer>Campus Assistant <span>Academic Outcome Engine · Pilot v0.2</span></footer>
    </section>
  </main>
</div>

